 void createMap(){try{tileTemplate=store.setting(aid,"location.tileTemplate",tileTemplate);tileAttribution=store.setting(aid,"location.tileAttribution",tileAttribution);tiles=new MapTiles(this,aid,tileTemplate);}catch(Exception e){message("地图服务设置无效，请重新配置");}map=new WebView(this);map.setBackgroundColor(0xffe9eef6);WebSettings s=map.getSettings();s.setJavaScriptEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setDomStorageEnabled(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setCacheMode(WebSettings.LOAD_DEFAULT);s.setUserAgentString(s.getUserAgentString()+" StudentTong/0.3.0 (https://github.com/saldienses/StudentTong)");CookieManager.getInstance().setAcceptThirdPartyCookies(map,false);map.addJavascriptInterface(new Bridge(),"MapBridge");map.setWebChromeClient(new WebChromeClient(){public boolean onConsoleMessage(ConsoleMessage m){if(m.messageLevel()==ConsoleMessage.MessageLevel.ERROR)message("地图资源加载异常，可手动输入坐标");return true;}});map.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){android.net.Uri u=r.getUrl();if("studenttong-map.local".equals(u.getHost())&&"https".equals(u.getScheme())){String name=u.getLastPathSegment();if(!Arrays.asList("index.html","leaflet.js","leaflet.css").contains(name))return empty();try{return new WebResourceResponse(name.endsWith(".js")?"application/javascript":name.endsWith(".css")?"text/css":"text/html","UTF-8",getAssets().open("map/"+name));}catch(Exception e){return empty();}}if(tiles!=null&&tiles.matches(u.toString()))return tiles.get(u.toString());return empty();}public void onReceivedSslError(WebView v,SslErrorHandler h,android.net.http.SslError e){h.cancel();message("地图证书校验失败，可手动输入坐标");}});try(InputStream in=getAssets().open("map/index.html")){map.loadDataWithBaseURL("https://studenttong-map.local/",MainActivity.read(in,200000).replace("__TILE_TEMPLATE__",JSONObject.quote(tileTemplate)).replace("__TILE_ATTRIBUTION__",JSONObject.quote(tileTemplate.equals("https://tile.openstreetmap.org/{z}/{x}/{y}.png")?"© <a href=\"https://www.openstreetmap.org/copyright\">OpenStreetMap</a> contributors":MainActivity.escape(tileAttribution))),"text/html","UTF-8",null);}catch(Exception e){android.util.Log.e("StudentTongMap","Local map resource failed",e);message("本地地图资源加载失败，可手动输入坐标");}}
 WebResourceResponse empty(){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}void js(String code){if(map!=null&&!dead)map.evaluateJavascript(code,null);}
 final class Bridge { @JavascriptInterface public void selected(double lat,double lon,String label){handler.post(()->{try{selected=new PreviewLocation(lat,lon,10,label);updatePoint();}catch(Exception e){message("无效地图坐标");}});}@JavascriptInterface public void ready(){handler.post(()->{mapReady=true;if(selected!=null)setPoint(selected,true);});}@JavascriptInterface public void mapError(String s){handler.post(()->{if(!diagnostics)message("底图加载失败，可搜索或手动输入坐标");});}@JavascriptInterface public void tilesReady(){handler.post(()->{if(!diagnostics&&status!=null)message("WGS-84 · 地图底图已加载");});}@JavascriptInterface public void previewState(String s){handler.post(()->{if(Arrays.asList("running","paused","stopped","completed").contains(s)){previewState=s;updateModes();if(!diagnostics)message("本地路线预览："+previewLabel()+" · 不改变系统定位");}});}}
 void search(String query){if(query.trim().isEmpty()){message("请输入地点");return;}message("正在查询地点…");worker.submit(()->{try{JSONArray rows=new LocationSearchManager(store,aid).search(query);handler.post(()->{if(dead||diagnostics)return;results.removeAllViews();if(rows.length()==0){message("没有结果，可手动输入坐标");return;}ScrollView scroll=new ScrollView(this);LinearLayout list=col();scroll.addView(list);for(int i=0;i<rows.length();i++){PreviewLocation p=PreviewLocation.parse(rows.optJSONObject(i));Button b=button(p.label,()->{setPoint(p,true);results.removeAllViews();((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);});b.setMaxLines(2);list.addView(b);}results.addView(scroll,new LinearLayout.LayoutParams(-1,Ui.dp(this,140)));message("选择搜索结果 · © OpenStreetMap contributors");});}catch(Exception e){handler.post(()->message("地点服务不可达，可手动输入坐标或更换地理服务"));}});}
 void reverse(){if(selected==null){message("请先选点");return;}final PreviewLocation p=selected;message("正在解析所选位置地址…");worker.submit(()->{try{String name=new LocationSearchManager(store,aid).reverse(p);handler.post(()->{if(selected==p)setPoint(new PreviewLocation(p.latitude,p.longitude,p.accuracy,name),false);});}catch(Exception e){handler.post(()->message("地点服务不可达，可手动输入坐标或更换地理服务"));}});}
 EditText field(LinearLayout p,String hint,String value){p.addView(text(hint,12));EditText e=new EditText(this);e.setText(value);e.setSingleLine(true);e.setTextSize(14);p.addView(e);return e;}
 void editCoordinates(){LinearLayout p=col();p.setPadding(Ui.dp(this,20),0,Ui.dp(this,20),0);EditText lat=field(p,"纬度（WGS-84）",selected==null?"":Double.toString(selected.latitude)),lon=field(p,"经度（WGS-84）",selected==null?"":Double.toString(selected.longitude));lat.setInputType(12290);lon.setInputType(12290);AlertDialog d=new AlertDialog.Builder(this).setTitle("手动输入坐标").setView(p).setPositiveButton("确认",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{setPoint(new PreviewLocation(Double.parseDouble(lat.getText().toString()),Double.parseDouble(lon.getText().toString()),10,"手动坐标"),true);d.dismiss();}catch(Exception e){lat.setError("纬度±90，经度±180，必须是有效数字");}}));d.show();}
 void confirmPoint(){try{if(selected==null)throw new Exception("请先选点");store.setSetting(aid,"location.selected",selected.json().toString());message("已确认地图选点 · 尚未开启系统模拟定位");new AlertDialog.Builder(this).setTitle("已确认选点").setMessage("该点仍为本地预览。开启系统模拟定位需要单独授权和确认；签到仍从系统接口读取定位。").setNegativeButton("继续预览",null).setPositiveButton("定位管理",(d,n)->mockPanel()).show();}catch(Exception e){message(e.getMessage());}}
 void save(){try{if(selected==null)throw new Exception("请先选点");EditText name=new EditText(this);name.setText(selected.label);new AlertDialog.Builder(this).setTitle("保存常用位置").setView(name).setPositiveButton("保存",(d,n)->{try{PreviewLocation p=new PreviewLocation(selected.latitude,selected.longitude,selected.accuracy,name.getText().toString());history.add("history",p.json());message("已保存到当前账号");}catch(Exception e){message(e.getMessage());}}).setNegativeButton("取消",null).show();}catch(Exception e){message(e.getMessage());}}
 void history(boolean corrections){try{JSONArray rows=history.list(corrections?"corrections":"history");if(rows.length()==0){message("当前账号暂无"+(corrections?"修正记录":"常用位置"));return;}String[] names=new String[rows.length()];for(int i=0;i<rows.length();i++){JSONObject j=rows.getJSONObject(i);names[i]=corrections?j.optString("reason")+" · "+new java.text.SimpleDateFormat("MM-dd HH:mm",Locale.CHINA).format(new Date(j.optLong("started"))):j.optString("label");}new AlertDialog.Builder(this).setTitle(corrections?"本机修正记录":"常用位置 · 当前账号").setItems(names,(d,n)->{JSONObject j=rows.optJSONObject(n);AlertDialog.Builder view=new AlertDialog.Builder(this).setTitle(names[n]).setMessage(corrections?"修正原因："+j.optString("reason")+"\n开始："+new Date(j.optLong("started"))+"\n结束："+new Date(j.optLong("ended"))+"\n状态："+j.optString("state")+"\n精度："+j.optDouble("accuracy")+" 米\n"+j.optString("message")+"\n修正前："+(j.optJSONObject("before")==null?"未读取到有效真实位置":j.optJSONObject("before").optDouble("latitude")+", "+j.optJSONObject("before").optDouble("longitude"))+"\n选点："+(j.optJSONObject("selected")==null?"无":j.optJSONObject("selected").optDouble("latitude")+", "+j.optJSONObject("selected").optDouble("longitude")):String.format(Locale.ROOT,"%s\n纬度 %.6f\n经度 %.6f\n坐标体系 WGS-84",j.optString("label"),j.optDouble("latitude"),j.optDouble("longitude"))).setNegativeButton("关闭",null).setNeutralButton("删除",(x,k)->new AlertDialog.Builder(this).setMessage("删除这条本机记录？").setNegativeButton("取消",null).setPositiveButton("删除",(y,z)->{try{history.delete(corrections?"corrections":"history",j.optString("id"));message("记录已删除");}catch(Exception e){message(e.getMessage());}}).show());if(!corrections)view.setPositiveButton("使用位置",(x,k)->setPoint(PreviewLocation.parse(j),true));view.show();}).show();}catch(Exception e){message(e.getMessage());}}
 void guidance(){new AlertDialog.Builder(this).setTitle("系统模拟定位授权").setMessage("手机设置 → 开发者选项 → 选择模拟位置信息应用 → 学生通。\n\n必须由你手动选择；软件不会自行修改系统安全设置。仅用于已获教师授权的位置修正，Android与其他应用仍可识别Mock标记。").setPositiveButton("打开开发者选项",(d,n)->{try{startActivity(new Intent(Settings.ACTION_APPLICATION_DEVELOPMENT_SETTINGS));}catch(Exception e){startActivity(new Intent(Settings.ACTION_SETTINGS));}}).setNegativeButton("关闭",null).show();}
 void mockPanel(){String[] items={"开始模拟","暂停模拟","恢复模拟","停止模拟","授权说明 / 打开设置","重新检查授权","定位诊断","解析地址","路线预览","修正记录","地理服务设置","地图底图服务"};new AlertDialog.Builder(this).setTitle(LocationModeManager.label(this,aid)).setItems(items,(d,n)->{if(n==0)configureMock();else if(n<4)command(n==1?MockLocationService.PAUSE:n==2?MockLocationService.RESUME:MockLocationService.STOP);else if(n==4)guidance();else if(n==5)message(LocationModeManager.authorized(this)?"模拟应用授权已允许；运行还需检查定位权限及系统回读":"尚未选择学生通为模拟位置应用");else if(n==6){diagnostics=true;render();}else if(n==7)reverse();else if(n==8)routeMenu();else if(n==9)history(true);else if(n==10)geocoder();else tileSettings();}).show();}
 void configureMock(){try{if(selected==null)throw new Exception("请先在地图选点");if(!LocationModeManager.authorized(this)){guidance();return;}if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=0){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},70);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0){requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},71);return;}JSONObject runtime=LocationModeManager.runtime(this);if(Arrays.asList("running","starting","paused").contains(runtime.optString("state"))){throw new Exception("请先停止当前模拟；仅能管理一个系统模拟定位服务");}LinearLayout p=col();p.setPadding(Ui.dp(this,18),0,Ui.dp(this,18),0);EditText interval=field(p,"更新间隔（秒，1至60）","2"),accuracy=field(p,"精度（米，1至2000）",Double.toString(selected.accuracy)),altitude=field(p,"海拔（米）","0"),speed=field(p,"速度（m/s）","0"),bearing=field(p,"方向（0至360，不含360）","0");Spinner reason=new Spinner(this);reason.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"GPS 定位漂移","室内信号较差","定位精度不足","其他经教师允许的原因"}));p.addView(reason);ScrollView scroll=new ScrollView(this);scroll.addView(p);AlertDialog d=new AlertDialog.Builder(this).setTitle("模拟定位参数 · WGS-84").setView(scroll).setNegativeButton("取消",null).setPositiveButton("下一步",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(b->{try{JSONObject j=new JSONObject().put("aid",aid).put("point",new PreviewLocation(selected.latitude,selected.longitude,Double.parseDouble(accuracy.getText().toString()),selected.label).json()).put("interval",(long)(Double.parseDouble(interval.getText().toString())*1000)).put("altitude",Double.parseDouble(altitude.getText().toString())).put("speed",Double.parseDouble(speed.getText().toString())).put("bearing",Double.parseDouble(bearing.getText().toString())).put("reason",reason.getSelectedItem().toString()).put("before",realBefore);new MockLocationConfig(j);d.dismiss();new AlertDialog.Builder(this).setTitle("开启系统模拟定位？").setMessage("即将开启系统模拟定位。Android 和第三方应用可能识别该位置为模拟位置，请确认该操作符合教师授权的考勤修正要求。").setNegativeButton("取消",null).setPositiveButton("确认开启",(x,n)->{try{Intent intent=new Intent(this,MockLocationService.class).setAction(MockLocationService.START).putExtra("aid",aid).putExtra("config",j.toString());startForegroundService(intent);message("已请求启动；等待系统回读验证");}catch(Exception e){message("系统不允许启动定位服务，请检查权限并保持应用前台");}}).show();}catch(Exception e){interval.setError("参数无效，请检查坐标、精度、间隔和速度方向");}}));d.show();}catch(Exception e){message(e.getMessage());}}
 void command(String action){try{if(!action.equals(MockLocationService.STOP)&&!LocationModeManager.serviceAlive(this)){message("当前没有模拟服务，请先开始模拟");return;}startService(new Intent(this,MockLocationService.class).setAction(action).putExtra("aid",aid));message("已请求"+action+"，请查看定位诊断实际状态");}catch(Exception e){message("服务控制失败，请检查系统设置");}}
 void routeMenu(){String[] names={"将选中位置设为起点","开始路线预览（当前选点为终点）","暂停预览","恢复预览","停止预览"};new AlertDialog.Builder(this).setTitle("仅本地路线 · "+previewLabel()).setItems(names,(d,n)->{if(selected==null){message("请先选点");return;}if(n==0)js("setStart("+selected.latitude+","+selected.longitude+")");else js("preview('"+(n==1?"start":n==2?"pause":n==3?"resume":"stop")+"',"+selected.latitude+","+selected.longitude+")");}).show();}
 void geocoder(){EditText e=new EditText(this);e.setSingleLine(true);e.setText(store.setting(aid,"geocoder","https://nominatim.openstreetmap.org"));new AlertDialog.Builder(this).setTitle("地理编码服务").setMessage("仅主动搜索/解析地址时发送查询或坐标。默认Nominatim，©OpenStreetMap。可更换兼容的HTTPS服务；未保存任何API Key。").setView(e).setNegativeButton("取消",null).setPositiveButton("保存",(d,n)->{try{store.setSetting(aid,"geocoder",LocationSearchManager.endpoint(e.getText().toString().trim()));message("服务已保存");}catch(Exception x){message(x.getMessage());}}).show();}
 void tileSettings(){LinearLayout p=col();p.setPadding(Ui.dp(this,16),0,Ui.dp(this,16),0);EditText url=field(p,"HTTPS瓦片模板",tileTemplate),credit=field(p,"必须显示的数据来源署名",tileAttribution);new AlertDialog.Builder(this).setTitle("地图底图服务").setMessage("默认OpenStreetMap；可使用你有权使用的WGS84/标准Web Mercator瓦片服务。坐标不可用GCJ02底图冒充WGS84。仅加载可见瓦片，不批量下载。").setView(p).setNegativeButton("取消",null).setPositiveButton("保存",(d,n)->{try{MapTiles.validate(url.getText().toString());if(credit.getText().toString().trim().isEmpty())throw new Exception("请保留地图来源署名");store.setSetting(aid,"location.tileTemplate",url.getText().toString());store.setSetting(aid,"location.tileAttribution",credit.getText().toString());if(map!=null){map.destroy();map=null;}mapReady=false;render();message("底图设置已保存");}catch(Exception e){message(e.getMessage());}}).show();}
 void getReal(){if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=0){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION,android.Manifest.permission.ACCESS_COARSE_LOCATION},70);return;}cancelFix();Location best=null;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{Location l=locations.getLastKnownLocation(provider);if(!LocationModeManager.isMock(l)&&SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos())&&(best==null||l.getAccuracy()<best.getAccuracy()))best=l;}catch(Exception ignored){}if(best!=null){gotReal(best);return;}listener=new LocationListener(){public void onLocationChanged(Location l){if(!LocationModeManager.isMock(l)&&SignLogic.fresh(l,SystemClock.elapsedRealtimeNanos())){cancelFix();gotReal(l);}}public void onStatusChanged(String p,int s,Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};boolean requested=false;for(String provider:new String[]{LocationManager.GPS_PROVIDER,LocationManager.NETWORK_PROVIDER})try{if(locations.isProviderEnabled(provider)){locations.requestLocationUpdates(provider,1000,0,listener,Looper.getMainLooper());requested=true;}}catch(Exception ignored){}if(!requested){cancelFix();message("未启用正常定位Provider，请在系统中开启定位");return;}message("正在读取非Mock系统定位…");locationTimeout=()->{cancelFix();message("未获得新鲜的非Mock位置；没有伪造真实定位");};handler.postDelayed(locationTimeout,20000);}
 void gotReal(Location l){try{realBefore=LocationModeManager.fix(l);store.setSetting(aid,"location.lastReal",realBefore.toString());if(mapReady)js("actualFix("+l.getLatitude()+","+l.getLongitude()+",false)");setPoint(new PreviewLocation(l.getLatitude(),l.getLongitude(),l.getAccuracy(),LocationModeManager.source(l)),true);message("绿色：系统位置；蓝色：选中位置");}catch(Exception e){message(e.getMessage());}}
 void cancelFix(){if(locationTimeout!=null)handler.removeCallbacks(locationTimeout);if(listener!=null)try{locations.removeUpdates(listener);}catch(Exception ignored){}listener=null;}
 void diagnostics(){ScrollView scroll=new ScrollView(this);LinearLayout p=col();scroll.addView(p);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));TextView info=text("",14);info.setTag("diagnostics");Ui.card(p).addView(info);LinearLayout controls=row();add(controls,button("获取真实位置",()->getReal()));add(controls,button("授权设置",()->guidance()));add(controls,button("停止 / 清理",()->command(MockLocationService.STOP)));p.addView(controls);p.addView(button("修正记录",()->history(true)));p.addView(button("常用位置",()->history(false)));p.addView(button("模拟定位管理",()->mockPanel()));p.addView(text("独立Provider不会替换GPS/网络Provider。第三方应用是否选择此Provider取决于其实现；平台拒绝Mock时不会隐藏标记或绕过。",12));refreshDiagnostics();}
 void refreshDiagnostics(){if(!diagnostics)return;TextView v=root.findViewWithTag("diagnostics");if(v==null)return;JSONObject j=LocationModeManager.runtime(this);StringBuilder b=new StringBuilder(LocationModeManager.label(this,aid));b.append("\n模拟授权：").append(LocationModeManager.authorized(this)?"已允许":"未允许");b.append("\n精确定位权限：").append(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)==0?"已允许":"未允许");b.append("\n定位服务：").append(locations.isLocationEnabled()?"已开启":"未开启");if(aid.equals(j.optString("aid"))){b.append("\n服务实际存活：").append(LocationModeManager.serviceAlive(this)).append("\n服务状态：").append(j.optString("state","stopped")).append("\nProvider：").append(j.optString("provider","无")).append("\n已注册：").append(j.optBoolean("registered")).append("\n").append(j.optString("message"));JSONObject fix=j.optJSONObject("fix");if(fix!=null)b.append("\n最近验证 WGS-84：\n").append(fix.optDouble("latitude")).append(", ").append(fix.optDouble("longitude")).append("\n精度：").append(fix.optDouble("accuracy")).append("米\nMock：").append(fix.optBoolean("isMock")).append("\n时间：").append(new Date(fix.optLong("time")));String provider=j.optString("provider");if(!provider.isEmpty())b.append("\n系统中仍存在：").append(locations.getAllProviders().contains(provider));}else b.append(j.has("aid")?"\n未显示其他账号的坐标和记录":"\n本账号暂无模拟定位记录");if(realBefore!=null)b.append("\n最近非Mock定位：").append(realBefore.optDouble("latitude")).append(", ").append(realBefore.optDouble("longitude"));try{Location live=null;for(String provider:locations.getProviders(true)){Location fix=locations.getLastKnownLocation(provider);if(SignLogic.fresh(fix,SystemClock.elapsedRealtimeNanos())&&LocationModeManager.accepts(this,aid,fix)&&(live==null||fix.getAccuracy()<live.getAccuracy()))live=fix;}b.append("\n当前系统读取：");if(live==null)b.append("暂无新鲜有效定位");else b.append(LocationModeManager.source(live)).append("\n").append(live.getLatitude()).append(", ").append(live.getLongitude()).append("\n精度 ").append(live.getAccuracy()).append("米 · Mock ").append(LocationModeManager.isMock(live)).append("\n定位时间 ").append(new Date(live.getTime()));}catch(SecurityException denied){b.append("\n当前系统读取：无定位权限");}v.setText(b.toString());}
 final Runnable refresh=new Runnable(){public void run(){if(dead)return;updateModes();refreshDiagnostics();handler.postDelayed(this,1000);}};
 public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(g.length==0||g[0]!=PackageManager.PERMISSION_GRANTED){message("权限被拒绝，未开启模拟或提交签到。可在系统应用权限中重新授权。");return;}message("权限已允许，请重新执行所需操作");}
 protected void onResume(){super.onResume();if(root!=null&&diagnostics)refreshDiagnostics();}protected void onPause(){if(map!=null)js("if(typeof preview==='function')preview('pause',0,0)");super.onPause();}
 public void onBackPressed(){if(diagnostics){diagnostics=false;render();}else super.onBackPressed();}protected void onDestroy(){dead=true;cancelFix();handler.removeCallbacksAndMessages(null);worker.shutdownNow();if(map!=null){map.removeJavascriptInterface("MapBridge");map.stopLoading();map.destroy();}store.close();super.onDestroy();}
